window.AUTH=window.AUTH||{};window.AUTH["17-765"]={"d":"17-765","id":"2018/17-765","n":"United States v. Stitt","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2018-06-26","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/51424/20180626164915138_17-765tsUnitedStates.pdf","side":"pet","n":33},{"k":"respondent","label":"Brief of respondent Jason Daniel Sims (in 17-766)","date":"2018-08-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/59469/20180814163051174_1%20-%20Sims%20-%20Brief%20for%20Respondent.pdf","side":"res","n":60},{"k":"respondent","label":"Brief of respondent Victor Stitt, II","date":"2018-08-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/59388/20180814133144856_Brief.pdf","side":"res","n":42},{"k":"reply","label":"Reply of petitioner United States","date":"2018-09-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/63669/20180913164113063_17-765rbUnitedStates.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-765_2co3.pdf","tr":true,"items":[{"t":"case","label":"Central Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"by":{"0":"34"}},{"t":"case","label":"Collins v. Virginia","cite":"138 S. Ct. 1663","y":2018,"id":"2017/16-1027","sc":1,"by":{"0":"27","3":"13"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"by":{"0":"6","1":"3, 30, 37, 40","2":"23, 29, 33","3":"19"},"q":[{"src":"brief","b":1,"text":"[i]n case after case, . . . to expend resources examining (often aged) documents for evidence that a defendant admitted in a plea colloquy, or a prosecutor showed at trial, facts that, although unnecessary to the crime of conviction, satisfy an element of the relevant generic offense.","cite":"570 U.S. at 270"}]},{"t":"case","label":"Favro v. State","cite":"46 S.W. 932","y":1898,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W./46/932/","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"protects the humble tenant in his tent as well as his more fortunate neighbor in his palace.","cite":"46 S.W. 932, 933"}]},{"t":"case","label":"Gonzales v. Duenas-Alvarez","cite":"549 U.S. 183","y":2007,"id":"2006/05-1629","sc":1,"by":{"0":"8, 36","1":"10, 34","2":"2, 20, 23"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"7","1":"1","2":"3, 28, 31, 32"},"q":[{"src":"brief","b":1,"text":"the Armed Career Criminal Act increases his prison term to a minimum of 15 years and a maximum of life,","cite":"135 S. Ct. 2551, 2555"},{"src":"brief","b":2,"text":"violates this guarantee by taking away someone’s life, liberty, or property under a criminal law so vague that it fails to give ordinary people fair notice of the conduct it punishes, or so standardless that it invites arbitrary enforcement.","cite":"135 S. Ct. at 2556"}]},{"t":"case","label":"Kanaras v. State","cite":"460 A.2d 61","y":1983,"court":"Md. Ct. Spec. App.","url":"https://www.courtlistener.com/c/A.2d/460/61/","by":{"0":"19"}},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"by":{"0":"6, 8, 36","1":"passim","2":"passim","3":"14, 19"},"q":[{"src":"brief","b":0,"text":"reaches a broader range of places","cite":"136 S. Ct. at 2250"},{"src":"brief","b":2,"text":"are not alternative elements, going to the creation of separate crimes. To the contrary, they lay out alternative ways of satisfying a single locational element.","cite":"136 S. Ct. at 2250"},{"src":"brief","b":2,"text":"suggested to Congress that it reconsider how the ACCA is written.","cite":"136 S. Ct. at 2257"},{"src":"argument","who":"Justice Ginsburg","text":"That wasn't the position that the government took prior -- prior to Mathis, was it? I thought that prior to Mathis, the government acknowledged that generic burglary did not include motor vehicles as habitations?"},{"src":"argument","who":"Ms. Ross","text":"Before Mathis, this issue didn't come up as often because, obviously, the government often had two arguments it could make. It would make a divisibility argument as well as a mobile dwellings argument, but the government did, in many of the court of appeals cases going back to the '90s and the early 2000s, actually make this argument."},{"src":"argument","who":"Mr. Fisher","text":"First, this Court's precedent, from Taylor on through to Mathis, make clear that when it comes to the burglary provision of ACCA, buildings and structures are in one category that are inside the statute, vehicles are in another category that are outside the statute, and this case involves quintessential vehicles."}]},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"by":{"0":"8, 36","2":"2, 20, 23"}},{"t":"case","label":"People v. Netznik","cite":"383 N.E.2d 640","y":1978,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/383/640/","by":{"0":"19"}},{"t":"case","label":"People v. Winhoven","cite":"237 N.W.2d 540","y":1975,"court":"Mich. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/237/540/","by":{"0":"19"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"by":{"0":"33","1":"16, 33"},"q":[{"src":"brief","b":0,"text":"the mistake of reading an opinion (in truth part of an opinion) like a statute.","cite":"442 U.S. 330, 341"},{"src":"brief","b":1,"text":"the language of an opinion is not always to be parsed as though we were dealing with the language of a statute.","cite":"442 U.S. 330, 341"}]},{"t":"case","label":"Richardson v. State","cite":"888 S.W.2d 822","y":1994,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/888/822/","by":{"0":"35"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"by":{"0":"6, 8, 36, 38","1":"passim","2":"passim","3":"14"},"q":[{"src":"brief","b":1,"text":"makes burglary a violent felony only if committed in a building or enclosed space (‘generic burglary’), not in a boat or motor vehicle.","cite":"544 U.S. 13, 15-16"},{"src":"brief","b":2,"text":"nearly [30] years having passed since Taylor came down, without any action by Congress to modify the statute as subject to [this Court’s] understanding . . . .","cite":"544 U.S. at 23"},{"src":"brief","b":2,"text":"[i]nnumerable criminal defendants have been unconstitutionally sentenced under the flawed rule of Almendarez-Torres.","cite":"544 U.S. at 28"},{"src":"argument","who":"Mr. Fisher","text":"And, third, if necessary, we would ask this Court to apply the Sixth Amendment rule that Justice Thomas announced in Apprendi and himself laid out in Mathis and Shepard, that ACCA itself violates the Sixth Amendment because it transgresses the jury trial right."}]},{"t":"case","label":"Smith v. United States","cite":"877 F.3d 720","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/877/720/","by":{"0":"22, 31","1":"23, 24","2":"23, 24"},"q":[{"src":"brief","b":2,"text":"it is unlikely that the Justices set out in Taylor to adopt a definition of generic burglary that is satisfied by no more than a handful of states – if by any.","cite":"877 F.3d at 724"}]},{"t":"case","label":"State v. Pierre","cite":"320 So. 2d 185","y":1975,"court":"La.","url":"https://www.courtlistener.com/c/So.%202d/320/185/","by":{"0":"24"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"passim"},"q":[{"src":"brief","b":0,"text":"Congress singled out burglary * * * because of its inherent potential for harm to persons.","cite":"495 U.S. 575, 588"},{"src":"brief","b":0,"text":"expand[] the predicate offenses triggering the sentence enhancement from ‘robbery or burglary’ to ‘a violent felony or serious drug offense.’","cite":"495 U.S. at 582"},{"src":"brief","b":1,"text":"the proper definition of the term ‘burglary’ in the 1986 statute.","cite":"495 U.S. 575"},{"src":"brief","b":1,"text":"capture all offenses of a certain level of seriousness that involve violence or an inherent risk thereof.","cite":"495 U.S. at 590"},{"src":"brief","b":2,"text":"corrects an error that occurred inadvertently when the definition of burglary was deleted from the Armed Career Criminal statute in 1986. The amendment reenacts the original definition which was intended to be broader than common law burglary.","cite":"495 U.S. at 590"},{"src":"brief","b":2,"text":"[A]bsent a plain indication to the contrary, federal laws are not to be construed so that their application is dependent on state law.","cite":"495 U.S. 575"},{"src":"brief","b":3,"text":"the criminal codes of most States,","cite":"495 U.S. at 598"},{"src":"brief","b":3,"text":"inherent potential for harm to persons,","cite":"495 U.S. at 588"}]},{"t":"case","label":"United States v. Grisel","cite":"488 F.3d 844","y":2007,"url":"https://www.courtlistener.com/c/F.3d/488/844/","by":{"0":"23, 37","1":"34","2":"22, 23, 32"},"q":[{"src":"brief","b":1,"text":"a state statute explicitly defines a crime more broadly than the generic definition, no ‘legal imagination,’ is required to hold that a realistic probability exists that the state will apply its statute to conduct that falls outside the generic definition of the crime. The state statute’s greater breadth is evident from its text.","cite":"488 F.3d 844, 850"}]},{"t":"case","label":"United States v. Herrold","cite":"883 F.3d 517","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/517/","by":{"0":"29, 30, 31, 32, 36","2":"passim"},"q":[{"src":"brief","b":0,"text":"[a] person would likely be present where the person is living.","cite":"883 F.3d at 550"},{"src":"brief","b":0,"text":"a traditional home or a ‘vehicle adapted for overnight accommodation.’","cite":"883 F.3d at 550"},{"src":"brief","b":2,"text":"The Court paid no attention to the limiting characteristics imposed by the Iowa statute – the requirement that any vehicle be ‘adapted for overnight accommodation of persons. . . .’ Instead, the Court flatly said that the Iowa statute is overbroad because it reaches ‘land, water, or air vehicle[s],’ full stop.","cite":"883 F.3d 517, 538"},{"src":"brief","b":2,"text":"If its approach were correct, it would make no sense to draw the line at vehicles-cum-dwellings – the tallying would require some larger subcategory of vehicles to count as viable locations for generic burglary.","cite":"883 F.3d at 541"}]},{"t":"case","label":"United States v. Lamb","cite":"847 F.3d 928","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/928/","by":{"0":"13","2":"22"}},{"t":"case","label":"United States v. Leonard","cite":"868 F.2d 1393","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/868/1393/","by":{"0":"35"}},{"t":"case","label":"United States v. Nance","cite":"481 F.3d 882","y":2007,"url":"https://www.courtlistener.com/c/F.3d/481/882/","by":{"0":"7"}},{"t":"case","label":"United States v. Priddy","cite":"808 F.3d 676","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/808/676/","by":{"0":"7"}},{"t":"case","label":"United States v. Rivera-Oros","cite":"590 F.3d 1123","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/590/1123/","by":{"0":"27","3":"11"},"q":[{"src":"brief","b":0,"text":"the unique wounds caused by residential burglary are independent of the size or construction of the dwelling. They are the same for the mansion house and the boarding house, the tract home and the mobile home.","cite":"590 F.3d 1123, 1130"}]},{"t":"case","label":"United States v. Spring","cite":"80 F.3d 1450","y":1996,"url":"https://www.courtlistener.com/c/F.3d/80/1450/","by":{"0":"27","2":"23, 24","3":"13"},"q":[{"src":"brief","b":0,"text":"the burglary of a mobile home or camper is often likely to pose a greater risk of violence to the occupant or owner than the burglary of a building or house because it is more difficult for the burglar to enter or escape unnoticed.","cite":"80 F.3d 1450, 1462"},{"src":"brief","b":3,"text":"pose[s] a greater risk of violence to the occupant or owner than the burglary of a building or house because it is more difficult for the burglar to enter or escape unnoticed.","cite":"80 F.3d 1450, 1462"}]},{"t":"case","label":"Will v. Michigan Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"by":{"0":"34"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2185","by":{"0":"3, 25"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)(2)(B)","(e)(2)(B)(ii)","(a)(2)","(e)","(e)(1)","(g)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 3","1":"1, 9, 1, 1","2":"2, 7, 7, 10, 2","3":"1"},"q":[{"src":"brief","b":0,"text":"is burglary, arson, or extortion, [or] involves use of explosives.","cite":"18 U.S.C. 924(e)(2)(B)(ii)"},{"src":"brief","b":1,"text":"has three previous convictions . . . for a violent felony or a serious drug offense,","cite":"18 U.S.C. § 924(e)(1)"},{"src":"brief","b":2,"text":"any crime punishable by a term of imprisonment exceeding one year and consisting of entering or remaining surreptitiously within a building that is property of another with intent to engage in conduct constituting a Federal or State offense.","cite":"18 U.S.C. § 924(e)"}]},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"0":"4","2":"8, 10-11","3":"3"}},{"t":"law","label":"and guideline—Continued: Firearm Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/459","by":{"0":"3, 25","2":"7"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)","(g)","(g)(9)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 3, 6, 11","1":"1, 3","3":"7"}},{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"by":{"1":"43","3":"19"},"q":[{"src":"brief","b":1,"text":"Because [the previous decision was] irreconcilable with the reasoning of Apprendi and the original meaning of the Sixth Amendment, [the Court] follow[ed] the latter.","cite":"570 U.S. 99, 116 n.5"}]},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1999,"id":"1997/96-6839","sc":1,"by":{"1":"7, 42","2":"7, 35","3":"18"}},{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"by":{"1":"40, 42, 43","3":"18, 19"},"q":[{"src":"argument","who":"Mr. Fisher","text":"And, third, if necessary, we would ask this Court to apply the Sixth Amendment rule that Justice Thomas announced in Apprendi and himself laid out in Mathis and Shepard, that ACCA itself violates the Sixth Amendment because it transgresses the jury trial right."}]},{"t":"case","label":"Bell v. United States","cite":"349 U.S. 81","y":1955,"id":"scdb/1954-072","sc":1,"by":{"1":"24"}},{"t":"case","label":"Busic v. United States","cite":"446 U.S. 398","y":1980,"id":"1979/78-6020","sc":1,"by":{"1":"24"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"serves to ensure both that there is fair warning of the boundaries of criminal conduct and that legislatures, not courts, define criminal liability.","cite":"494 U.S. 152, 158"}]},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"by":{"1":"21, 30","3":"3, 4, 9"},"q":[{"src":"brief","b":1,"text":"is not required by the categorical approach.","cite":"137 S. Ct. 1562, 1571 n.3"},{"src":"brief","b":3,"text":"a multijuris- dictional analysis ‘is not required by the categorical approach.’","cite":"137 S. Ct. at 1571 n.3"}]},{"t":"case","label":"Harris v. United States","cite":"536 U.S. 545","y":2002,"id":"2001/00-10666","sc":1,"by":{"1":"43"}},{"t":"case","label":"Hilton v. S.C. Pub. Rys. Comm’n","cite":"502 U.S. 197","y":1991,"id":"1991/90-848","sc":1,"by":{"1":"16"}},{"t":"case","label":"Holbrook v. Healthport, Inc.","cite":"432 S.W.3d 593","y":2014,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/432/593/","by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"gives meaning and effect to every word in the statute, if possible.","cite":"432 S.W.3d 593, 597"}]},{"t":"case","label":"Hylton v. Sessions, ___ F.3d ___","cite":"2018 WL 3483561","y":2018,"court":"2d Cir. July 20","by":{"1":"34, 36"},"q":[{"src":"brief","b":1,"text":"wrench[] the Supreme Court’s language in Duenas-Alvarez from its context.","cite":"2018 WL 3483561"}]},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"by":{"1":"22"}},{"t":"case","label":"Lozman v. City of Riviera Beach, Fla.","cite":"568 U.S. 115","y":2013,"id":"2012/11-626","sc":1,"by":{"1":"13"},"q":[{"src":"brief","b":1,"text":"differs significantly from an ordinary houseboat in that it has no ability to propel itself","cite":"568 U.S. 115, 122"}]},{"t":"case","label":"Mellouli v. Holder","cite":"719 F.3d 995","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/719/995/","by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"there [was] little more than a ‘theoretical possibility’ that a conviction under Kansas law will not involve a controlled substance as defined [under the generic offense].","cite":"719 F.3d 995, 997"}]},{"t":"case","label":"Mellouli v. Lynch","cite":"135 S. Ct. 1980","y":2015,"id":"2014/13-1034","sc":1,"by":{"1":"30, 31, 37"},"q":[{"src":"brief","b":1,"text":"no Kansas paraphernalia prosecutions involving nonfederally-controlled substances.","cite":"135 S. Ct. 1980"}]},{"t":"case","label":"Mendieta-Robles v. Gonzales","cite":"226 F. App’x 564","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/226/564/","by":{"1":"35"}},{"t":"case","label":"Missouri v. Frye","cite":"566 U.S. 134","y":2012,"id":"2011/10-444","sc":1,"by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"ninety-four percent of state convictions are the result of guilty pleas.","cite":"566 U.S. 134, 143"}]},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"by precluding the relitigation of past convictions in minitrials conducted long after the fact.","cite":"569 U.S. 184, 200-01"}]},{"t":"case","label":"Nat’l Home Centers, Inc. v. Coleman","cite":"283 S.W.3d 218","y":2008,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/283/218/","by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"the plain language of the statute . . . is clear and unambiguous . . . the plain meaning of the words","cite":"283 S.W.3d 218, 222"}]},{"t":"case","label":"Nunez v. Holder","cite":"594 F.3d 1124","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/594/1124/","by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"lack of published cases or appel- late-level cases does not imply a lack of convictions.","cite":"594 F.3d 1124, 1137 n.10"}]},{"t":"case","label":"Ramos v. U.S. Att’y Gen.","cite":"709 F.3d 1066","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/709/1066/","by":{"1":"35"}},{"t":"case","label":"Rivers v. Roadway Exp., Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"an authoritative statement of what the statute meant before as well as after the decision of the case giving rise to that construction.","cite":"511 U.S. 298, 312-13"}]},{"t":"case","label":"Singh v. U.S. Att’y Gen.","cite":"839 F.3d 273","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/839/273/","by":{"1":"35"}},{"t":"case","label":"State v. Reeves","cite":"574 S.W.2d 647","y":1978,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.2d/574/647/","by":{"1":"33"}},{"t":"case","label":"State v. Ryun","cite":"549 S.W.2d 141","y":1977,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/549/141/","by":{"1":"12"}},{"t":"case","label":"Swaby v. Yates","cite":"847 F.3d 62","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/847/62/","by":{"1":"34"}},{"t":"case","label":"United States v. Aguila-Montes de Oca","cite":"655 F.3d 915","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/915/","by":{"1":"18"}},{"t":"case","label":"United States v. Brumback","cite":"614 F. App’x 288","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/614/288/","by":{"1":"33"}},{"t":"case","label":"United States v. Faulls","cite":"821 F.3d 502","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/502/","by":{"1":"18"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"1":"24"}},{"t":"case","label":"United States v. Henriquez","cite":"757 F.3d 144","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/144/","by":{"1":"35","2":"22"}},{"t":"case","label":"United States v. Rainer","cite":"616 F.3d 1212","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/616/1212/","by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"focus[es] on the nature of the property or place, not on the nature of its use at the time of the crime.","cite":"616 F.3d 1212, 1215"}]},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"by":{"1":"31"}},{"t":"case","label":"United States v. Thomas","cite":"2017 WL 6375741","y":2017,"court":"E.D.N.Y. Dec. 13","by":{"1":"19"}},{"t":"case","label":"United States v. Woods","cite":"571 U.S. 31","y":2013,"id":"2013/12-562","sc":1,"by":{"1":"33"}},{"t":"case","label":"Vasquez v. Sessions","cite":"138 S. Ct. 2697","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2697/","sc":1,"by":{"1":"35"}},{"t":"case","label":"Vasquez v. Sessions","cite":"885 F.3d 862","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/885/862/","by":{"1":"35"}},{"t":"case","label":"Vassell v. U.S. Att’y Gen.","cite":"839 F.3d 1352","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/1352/","by":{"1":"35"}},{"t":"case","label":"Wash. State Grange v. Wash. State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"a substantial number of [the challenged statute’s] applications are unconstitutional, judged in relation to the statute’s plainly legitimate sweep.","cite":"552 U.S. 442, 449 n.6"}]},{"t":"case","label":"Watson v. United States","cite":"552 U.S. 74","y":2007,"id":"2007/06-571","sc":1,"by":{"1":"17"}},{"t":"case","label":"Whyte v. Lynch","cite":"807 F.3d 463","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/807/463/","by":{"1":"38"}},{"t":"usc","label":"18 U.S.C. § 48","url":"https://www.law.cornell.edu/uscode/text/18/48","subs":["(c)"],"stext":{"head":"§48. Animal crushing","paras":[[0,"(a) Offenses.—"],[1,"(1) Crushing.—It shall be unlawful for any person to purposely engage in animal crushing in or affecting interstate or foreign commerce or within the special maritime and territorial jurisdiction of the United States."],[1,"(2) Creation of animal crush videos.—It shall be unlawful for any person to knowingly create an animal crush video, if—"],[2,"(A) the person intends or has reason to know that the animal crush video will be distributed in, or using a means or facility of, interstate or foreign commerce; or"],[2,"(B) the animal crush video is distributed in, or using a means or facility of, interstate or foreign commerce."],[1,"(3) Distribution of animal crush videos.—It shall be unlawful for any person to knowingly sell, market, advertise, exchange, or distribute an animal crush video in, or using a means or facility of, interstate or foreign commerce."],[0,"(b) Extraterritorial Application.—This section applies to the knowing sale, marketing, advertising, exchange, distribution, or creation of an animal crush video outside of the United States, if—"],[1,"(1) the person engaging in such conduct intends or has reason to know that the animal crush video will be transported into the United States or its territories or possessions; or"],[1,"(2) the animal crush video is transported into the United States or its territories or possessions."],[0,"(c) Penalties.—Whoever violates this section shall be fined under this title, imprisoned for not more than 7 years, or both."],[0,"(d) Exceptions.—"],[1,"(1) In general.—This section does not apply with regard to any conduct, or a visual depiction of that conduct, that is—"],[2,"(A) a customary and normal veterinary, agricultural husbandry, or other animal management practice;"],[2,"(B) the slaughter of animals for food;"],[2,"(C) hunting, trapping, fishing, a sporting activity not otherwise prohibited by Federal law, predator control, or pest control;"],[2,"(D) medical or scientific research;"],[2,"(E) necessary to protect the life or property of a person; or"],[2,"(F) performed as part of euthanizing an animal."],[1,"(2) Good-faith distribution.—This section does not apply to the good-faith distribution of an animal crush video to—"],[2,"(A) a law enforcement agency; or"],[2,"(B) a third party for the sole purpose of analysis to determine if referral to a law enforcement agency is appropriate."],[1,"(3) Unintentional conduct.—This section does not apply to unintentional conduct that injures or kills an animal."],[1,"(4) Consistency with rfra.—This section shall be enforced in a manner that is consistent with section 3 of the Religious Freedom Restoration Act of 1993 (42 U.S.C. 2000bb–1)."],[0,"(e) No Preemption.—Nothing in this section shall be construed to preempt the law of any State or local subdivision thereof to protect animals."],[0,"(f) Definitions.—In this section—"],[1,"(1) the term \"animal crushing\" means actual conduct in which one or more living non-human mammals, birds, reptiles, or amphibians is purposely crushed, burned, drowned, suffocated, impaled, or otherwise subjected to serious bodily injury (as defined in section 1365 and including conduct that, if committed against a person and in the special maritime and territorial jurisdiction of the United States, would violate section 2241 or 2242);"],[1,"(2) the term \"animal crush video\" means any photograph, motion-picture film, video or digital recording, or electronic image that—"],[2,"(A) depicts animal crushing; and"],[2,"(B) is obscene; and"],[1,"(3) the term \"euthanizing an animal\" means the humane destruction of an animal accomplished by a method that—"],[2,"(A) produces rapid unconsciousness and subsequent death without evidence of pain or distress; or"],[2,"(B) uses anesthesia produced by an agent that causes painless loss of consciousness and subsequent death."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/48?type=usc&year=mostrecent&link-type=html"},"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"in which a living animal is intentionally maimed, mutilated, tortured, wounded, or killed.","cite":"18 U.S.C. § 48(c)"}]},{"t":"reg","label":"24 C.F.R. pt. 3280","url":"https://www.ecfr.gov/current/title-24/part-3280","by":{"1":"11"}},{"t":"reg","label":"24 C.F.R. pt. 3282","url":"https://www.ecfr.gov/current/title-24/part-3282","by":{"1":"11"}},{"t":"reg","label":"81 Fed. Reg. 6806","url":"https://www.govinfo.gov/link/fr/81/6806","by":{"1":"11"}},{"t":"case","label":"California v. Fleetwood","cite":"171 Cal. App. 3d 982","y":1985,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20App.%203d/171/982/","by":{"2":"32"},"q":[{"src":"argument","who":"Mr. Fisher","text":"And so, just as the Court has held in the Fourth Amendment context of California versus Carney, just as the HUD regulations that we cite at page 11 of our brief lay out, just as the state law like Tennessee lays out, just like local law, like local zoning law we cite on the same page of our brief, they all distinguish between floating homes and mobile homes, which are designed to be stationary on the one hand, and put those in the structure category, or a -- or a dwelling or a residence category."}]},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"by":{"2":"29"}},{"t":"case","label":"Dickerson v. New Banner Institute, Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"by":{"2":"10"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"by":{"2":"30"}},{"t":"case","label":"Cited Authorities Page Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"by":{"2":"30"},"q":[{"src":"brief","b":2,"text":"promotes the evenhanded, predictable, and consistent development of legal principles, fosters reliance on judicial decisions, and contributes to the actual and perceived integrity of the judicial process.","cite":"501 U.S. 808, 287"}]},{"t":"case","label":"Price v. Texas","cite":"2002 WL 471343","y":2002,"court":"Tex. App. Mar. 28","by":{"2":"32"},"q":[{"src":"brief","b":2,"text":"[W]hat makes [a vehicle] suitable or not suitable for overnight accommodation is a subjective factual question for the jury’s determination.","cite":"2002 WL 471343"}]},{"t":"case","label":"State v. Thompson","cite":"2015 WL 1756448","y":2015,"court":"Tenn. Crim. App. Apr. 15","by":{"2":"34"},"q":[{"src":"brief","b":2,"text":"[s]omething that belongs or is attached to something else.","cite":"2015 WL 1756448"}]},{"t":"case","label":"United States v. Bennett","cite":"100 F.3d 1105","y":1996,"court":"3rd Cir.","url":"https://www.courtlistener.com/c/F.3d/100/1105/","by":{"2":"22"}},{"t":"case","label":"United States v. Gundy","cite":"842 F.3d 1156","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/842/1156/","by":{"2":"22"}},{"t":"case","label":"United States v. Howard","cite":"742 F.3d 1334","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/742/1334/","by":{"2":"22"}},{"t":"case","label":"United States v. Lara","cite":"590 F. App’x 574","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/590/574/","by":{"2":"34"},"q":[{"src":"brief","b":2,"text":"[A]ppurtenant to’ can mean that an object is physically attached to another object, but it can also imply a relationship between two objects.","cite":"590 F.App’x 574, 579"}]},{"t":"case","label":"United States v. Moncrief","cite":"356 F. App’x 11","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/356/11/","by":{"2":"29"}},{"t":"case","label":"United States v. Narvarro","cite":"584 F. App’x 624","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/584/624/","by":{"2":"20"}},{"t":"case","label":"United States v. Naylor","cite":"887 F.3d 397","y":2018,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/887/397/","by":{"2":"26"}},{"t":"case","label":"United States v. Robinson","cite":"720 F. App’x 946","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/720/946/","by":{"2":"23"}},{"t":"case","label":"United States v. Silva","cite":"957 F.2d 157","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/957/157/","by":{"2":"23"}},{"t":"case","label":"Cited Authorities Page United States v. Sparks","cite":"265 F.3d 825","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/265/825/","by":{"2":"32"}},{"t":"case","label":"United States v. Stitt","cite":"860 F.3d 854","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/860/854/","by":{"2":"12, 14, 30, 33"},"q":[{"src":"brief","b":2,"text":"The Court could have said ‘building or structure or dwelling.’ It could have said ‘building or structure or other dwelling.’ It could have said ‘building or structure or other place adapted for overnight accommodation.’ But it didn’t. It said ‘building or structure.","cite":"860 F.3d 854, 858, 865"}]},{"t":"case","label":"United States v. Sweeten","cite":"933 F.2d 765","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/933/765/","by":{"2":"23"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"6, 31"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"2":"7, 35"}},{"t":"usc","label":"18 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/18/1202","subs":["(c)(9)"],"stext":{"head":"§1202. Ransom money","paras":[[0,"(a) Whoever receives, possesses, or disposes of any money or other property, or any portion thereof, which has at any time been delivered as ransom or reward in connection with a violation of section 1201 of this title, knowing the same to be money or property which has been at any time delivered as such ransom or reward, shall be fined under this title or imprisoned not more than ten years, or both."],[0,"(b) A person who transports, transmits, or transfers in interstate or foreign commerce any proceeds of a kidnapping punishable under State law by imprisonment for more than 1 year, or receives, possesses, conceals, or disposes of any such proceeds after they have crossed a State or United States boundary, knowing the proceeds to have been unlawfully obtained, shall be imprisoned not more than 10 years, fined under this title, or both."],[0,"(c) For purposes of this section, the term \"State\" has the meaning set forth in section 245(d) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1202?type=usc&year=mostrecent&link-type=html"},"by":{"2":"7, 7"},"q":[{"src":"brief","b":2,"text":"for robbery or burglary, or both.","cite":"18 U.S.C. § 1202"},{"src":"brief","b":2,"text":"any felony consisting of entering or remaining surreptitiously within a building that is property of another with intent to engage in conduct constituting a Federal or State offense.","cite":"18 U.S.C. § 1202(c)(9)"}]},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"by":{"3":"17"},"q":[{"src":"brief","b":3,"text":"settled and firm policy of deferring to regional courts of appeals,","cite":"487 U.S. 879, 908"}]},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"by":{"3":"15"}},{"t":"case","label":"Carachuri-Rosendo v. Holder","cite":"560 U.S. 563","y":2010,"id":"2009/09-60","sc":1,"by":{"3":"19"}},{"t":"case","label":"(I) Cases—Continued: Elk Grove Unified Sch. Dist. v. Newdow","cite":"542 U.S. 1","y":2004,"id":"2003/02-1624","sc":1,"by":{"3":"17"}},{"t":"case","label":"Kimble v. Marvel Ent’mt, LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"by":{"3":"16"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"3":"15"},"q":[{"src":"brief","b":3,"text":"only applies if, after considering text, structure, history, and purpose, there remains a grievous ambiguity or uncertainty in the statute such that the Court must simply guess as to what Congress intended.","cite":"570 U.S. 48, 76"}]},{"t":"case","label":"Scheidler v. National Org. for Women, Inc.","cite":"537 U.S. 393","y":2003,"id":"2002/01-1118","sc":1,"by":{"3":"9"}},{"t":"case","label":"Southern Union Co. v. United States","cite":"567 U.S. 343","y":2012,"id":"2011/11-94","sc":1,"by":{"3":"19"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"3":"7"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"by":{"3":"15"}},{"t":"case","label":"United States v. Tinklenberg","cite":"563 U.S. 647","y":2011,"id":"2010/09-1498","sc":1,"by":{"3":"16"},"q":[{"src":"brief","b":3,"text":"consider, or decline to entertain, alternative grounds for affirmance.","cite":"563 U.S. 647, 661"}]},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)(A)"],"by":{"3":"4"}}]};